import { test, expect } from '@playwright/test';

test.describe('Itemised Receipt After Checkout', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
    // Add items to cart
    await page.getByRole('button', { name: /add to cart/i }).first().click();
    await page.getByRole('button', { name: /add to cart/i }).nth(1).click();
  });

  test('should display itemised receipt with all purchased items', async ({ page }) => {
    // Navigate to checkout
    await page.getByRole('link', { name: /cart/i }).click();
    await page.getByRole('button', { name: /proceed to checkout/i }).click();

    // Fill in checkout details
    await page.getByLabel(/email/i).fill('test@example.com');
    await page.getByLabel(/full name/i).fill('John Doe');
    await page.getByLabel(/address/i).fill('123 Main St');
    await page.getByLabel(/city/i).fill('New York');
    await page.getByLabel(/zip/i).fill('10001');

    // Complete payment
    await page.getByRole('button', { name: /complete purchase/i }).click();

    // Verify receipt is displayed
    await expect(page.getByRole('heading', { name: /receipt/i })).toBeVisible();

    // Verify receipt contains itemised list
    const receiptItems = page.getByRole('list').filter({ has: page.getByText(/item/i) });
    await expect(receiptItems).toBeVisible();
  });

  test('should show item details including quantity and price on receipt', async ({ page }) => {
    // Navigate to checkout
    await page.getByRole('link', { name: /cart/i }).click();
    await page.getByRole('button', { name: /proceed to checkout/i }).click();

    // Fill in checkout details
    await page.getByLabel(/email/i).fill('customer@example.com');
    await page.getByLabel(/full name/i).fill('Jane Smith');
    await page.getByLabel(/address/i).fill('456 Oak Ave');
    await page.getByLabel(/city/i).fill('Los Angeles');
    await page.getByLabel(/zip/i).fill('90001');

    // Complete payment
    await page.getByRole('button', { name: /complete purchase/i }).click();

    // Verify receipt displays item names
    await expect(page.getByText(/product name/i)).toBeVisible();

    // Verify receipt displays quantities
    await expect(page.getByText(/qty|quantity/i)).toBeVisible();

    // Verify receipt displays prices
    await expect(page.getByText(/\$|price/i)).toBeVisible();

    // Verify total is displayed
    await expect(page.getByRole('heading', { name: /total/i })).toBeVisible();
  });

  test('should allow user to download or print receipt', async ({ page }) => {
    // Navigate to checkout
    await page.getByRole('link', { name: /cart/i }).click();
    await page.getByRole('button', { name: /proceed to checkout/i }).click();

    // Fill in checkout details
    await page.getByLabel(/email/i).fill('user@example.com');
    await page.getByLabel(/full name/i).fill('Bob Johnson');
    await page.getByLabel(/address/i).fill('789 Pine Rd');
    await page.getByLabel(/city/i).fill('Chicago');
    await page.getByLabel(/zip/i).fill('60601');

    // Complete payment
    await page.getByRole('button', { name: /complete purchase/i }).click();

    // Verify download/print options are available
    const downloadButton = page.getByRole('button', { name: /download|print/i });
    await expect(downloadButton).toBeVisible();
    await expect(downloadButton).toBeEnabled();
  });
});
